B.apV=s(['\uc774 \uc57d\uad00\uc740 \uc36c\uc6cd\uc2a4(\uc774\ud558 "\ud68c\uc0ac")\uac00 \uc81c\uacf5\ud558\ub294 \uc5b4\ud765!\ud55c\uc790 \uc571\uacfc \ucf58\ud150\uce20\ub97c \uc774\uc6a9\ud560 \ub54c \ud68c\uc0ac\uc640 \uc774\uc6a9\uc790\uc758 \uad8c\ub9ac, \uc758\ubb34, \ucc45\uc784\uc744 \uc815\ud574\uc694.'],t.s)
B.aI1=new A.ey("\uc81c1\uc870 (\ubaa9\uc801)",B.apV)
B.adn=s(['\xb7 "\uc571"\uc740 \ud68c\uc0ac\uac00 \uc571 \uc2a4\ud1a0\uc5b4\uc640 \uc6f9\uc73c\ub85c \uc81c\uacf5\ud558\ub294 \uc5b4\ud765!\ud55c\uc790 \ud55c\uc790 \ud559\uc2b5 \uc571\uc774\uc5d0\uc694.','\xb7 "\uc774\uc6a9\uc790"\ub294 \uc774 \uc57d\uad00\uc5d0 \ub530\ub77c \uc571\uc744 \uc4f0\ub294 \uc0ac\ub78c\uc774\uc5d0\uc694.','\xb7 "\ubb34\ub8cc \uccb4\ud5d8"\uc740 \uc774\uc6a9\uad8c \uc5c6\uc774 72\uc2dc\uac04 \ub3d9\uc548 \ubaa8\ub4e0 \ud559\uc2b5\uc744 \uc368 \ubcfc \uc218 \uc788\ub294 \uae30\uac04\uc774\uc5d0\uc694.','\xb7 "\uc774\uc6a9\uad8c"\uc740 \ubb34\ub8cc \uccb4\ud5d8\uc774 \ub05d\ub09c \ub4a4\uc5d0\ub3c4 \ud559\uc2b5\uc744 \uacc4\uc18d\ud560 \uc218 \uc788\ub3c4\ub85d \ud55c \ubc88 \uacb0\uc81c\ud574 \uc0ac\ub294 \ub514\uc9c0\ud138 \ucf58\ud150\uce20 \uc774\uc6a9 \uad8c\ub9ac\uc608\uc694.','\xb7 "\ucf58\ud150\uce20"\ub294 \uc571\uc774 \uc81c\uacf5\ud558\ub294 \ud55c\uc790, \ub0b1\ub9d0, \ubb38\uc81c, \uadf8\ub9bc, \uc74c\uc131, \uc774\uc57c\uae30 \uac19\uc740 \ud559\uc2b5 \uc790\ub8cc\uc608\uc694.'],t.s)
B.aI8=new A.ey("\uc81c2\uc870 (\uc6a9\uc5b4\uc758 \ub73b)",B.adn)
B.aiY=s(["\ud68c\uc0ac\ub294 \uc774 \uc57d\uad00\uc744 \uc571\uc758 \uc124\uc815 \ud654\uba74\uacfc \uc6f9 \ud398\uc774\uc9c0(https://hanja-app.sunw.kr/terms.html)\uc5d0 \uac8c\uc2dc\ud574\uc694.","\ud68c\uc0ac\ub294 \uad00\ub828 \ubc95\uc744 \uc5b4\uae30\uc9c0 \uc54a\ub294 \ubc94\uc704\uc5d0\uc11c \uc57d\uad00\uc744 \ubc14\uafc0 \uc218 \uc788\uc5b4\uc694.","\uc57d\uad00\uc744 \ubc14\uafb8\uba74 \ubc14\ub010 \ub0b4\uc6a9, \uc2dc\ud589\uc77c, \ubc14\uafb8\ub294 \uc774\uc720\ub97c \uc2dc\ud589 7\uc77c \uc804\ubd80\ud130 \uc571\uacfc \uc6f9 \ud398\uc774\uc9c0\uc5d0 \uc54c\ub824\uc694. \uc774\uc6a9\uc790\uc5d0\uac8c \ubd88\ub9ac\ud558\uac8c \ubc14\uafb8\uba74 \uc2dc\ud589 30\uc77c \uc804\ubd80\ud130 \uc54c\ub824\uc694.","\ubc14\ub010 \uc57d\uad00\uc5d0 \ub3d9\uc758\ud558\uc9c0 \uc54a\uc73c\uba74 \uc571 \uc774\uc6a9\uc744 \uba48\ucd9c \uc218 \uc788\uc5b4\uc694."],t.s)
B.aHW=new A.ey("\uc81c3\uc870 (\uc57d\uad00\uc758 \uac8c\uc2dc\uc640 \ubcc0\uacbd)",B.aiY)
B.ahH=s(["\xb7 \uc0c1\ud638: \uc36c\uc6cd\uc2a4","\xb7 \ub300\ud45c: \ub0a8\uc120","\xb7 \uc0ac\uc5c5\uc790\ub4f1\ub85d\ubc88\ud638: 463-11-02942","\xb7 \ud1b5\uc2e0\ud310\ub9e4\uc5c5 \uc2e0\uace0\ubc88\ud638: 2026-\uc11c\uc6b8\uc1a1\ud30c-2924","\xb7 \uc8fc\uc18c: \uc11c\uc6b8\ud2b9\ubcc4\uc2dc \uc1a1\ud30c\uad6c \uc704\ub840\uad11\uc7a5\ub85c 199, \uc131\ud76c\ud504\ub77c\uc790 501-3-10\ud638","\xb7 \uc804\ud654: 070-8717-8850","\xb7 \uc774\uba54\uc77c: support@sunworks.kr","\xb7 \uc0ac\uc5c5\uc790\uc815\ubcf4 \ud655\uc778: https://www.ftc.go.kr/bizCommPop.do?wrkr_no=4631102942"],t.s)
B.aHT=new A.ey("\uc81c4\uc870 (\uc0ac\uc5c5\uc790 \uc815\ubcf4)",B.ahH)
B.abS=s(["\ud68c\uc0ac\ub294 \ud55c\uc790 \uae09\uc218 \uc2dc\ud5d8 \uc900\ube44\ub97c \ub3d5\ub294 \ud559\uc2b5 \ucf58\ud150\uce20(\uce74\ub4dc \ud559\uc2b5, \uc4f0\uae30, \ubaa8\uc758\uc2dc\ud5d8 \ub4f1)\ub97c \uc81c\uacf5\ud574\uc694.","\uc571\uc740 \ud68c\uc6d0\uac00\uc785\uc774\ub098 \ub85c\uadf8\uc778 \uc5c6\uc774 \uc368\uc694.","\ud559\uc2b5 \uae30\ub85d\uc740 \uc774\uc6a9\uc790\uc758 \uae30\uae30 \uc548\uc5d0\ub9cc \uc800\uc7a5\ub3fc\uc694. \ud68c\uc0ac\ub294 \ud559\uc2b5 \uae30\ub85d\uc744 \ubc1b\uac70\ub098 \ubcf4\uad00\ud558\uc9c0 \uc54a\uc544\uc694."],t.s)
B.aI2=new A.ey("\uc81c5\uc870 (\uc11c\ube44\uc2a4 \ub0b4\uc6a9)",B.abS)
B.axI=s(["\ubb34\ub8cc \uccb4\ud5d8\uc740 \uae30\uae30 \ud55c \ub300\uc5d0 \ud55c \ubc88, 72\uc2dc\uac04\uc774\uc5d0\uc694. \uc571\uc744 \ucc98\uc74c \uc5f4\uace0 \uccab \uc124\uc815\uc744 \ub9c8\uce5c \ub4a4 \uccb4\ud5d8 \uc548\ub0b4\uac00 \ub098\uc624\ub294 \ub54c\ubd80\ud130 \uc2dc\uac04\uc774 \ud758\ub7ec\uc694.","\uccb4\ud5d8 \uc548\ub0b4\uc5d0\uc11c \uccb4\ud5d8 \uae30\uac04, \ub05d\ub098\ub294 \ub0a0\uc9dc\uc640 \uc2dc\uac01, \ub05d\ub09c \ub4a4 \ud544\uc694\ud55c \uc774\uc6a9\uad8c \uae08\uc561\uc744 \uba3c\uc800 \uc54c\ub824 \uc918\uc694.","\uccb4\ud5d8\uc740 \uc800\uc808\ub85c \uc720\ub8cc\ub85c \ubc14\ub00c\uc9c0 \uc54a\uc544\uc694.","\uccb4\ud5d8\uc774 \ub05d\ub098\uba74 \uc774\uc6a9\uad8c \uc5c6\uc774\ub294 \uc0c8 \ud559\uc2b5\uc744 \uc2dc\uc791\ud560 \uc218 \uc5c6\uc5b4\uc694.","\uccb4\ud5d8\uc774 \ub05d\ub098\ub3c4 \ud559\uc2b5 \uae30\ub85d \ubcf4\uae30, \ub0b4\ubcf4\ub0b4\uae30, \uc0ad\uc81c, \uad6c\ub9e4 \ubcf5\uc6d0, \ubb38\uc758\ub294 \uacc4\uc18d \uc4f8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aI_=new A.ey("\uc81c6\uc870 (\ubb34\ub8cc \uccb4\ud5d8)",B.axI)
B.ax8=s(["\uc774\uc6a9\uad8c\uc740 29,900\uc6d0\uc774\uace0 \ud55c \ubc88\ub9cc \uacb0\uc81c\ud574\uc694. \uc790\ub3d9 \uacb0\uc81c\ub098 \uad6c\ub3c5\uc740 \uc5c6\uc5b4\uc694.","\uc2e4\uc81c \uacb0\uc81c \uae08\uc561\uc740 \uad6c\ub9e4 \ud654\uba74\uacfc \uc2a4\ud1a0\uc5b4 \uacb0\uc81c \ucc3d\uc5d0 \ud45c\uc2dc\ub3fc\uc694.","\uc774\uc6a9\uad8c\uc740 \uc571\uc744 \ub0b4\ub824\ubc1b\uc740 \uc2a4\ud1a0\uc5b4\uc758 \uacb0\uc81c\ub85c \uc0ac\uc694. \uacb0\uc81c\ub294 \uadf8 \uc2a4\ud1a0\uc5b4\uc758 \uc808\ucc28\ub97c \ub530\ub77c\uc694.","\uc571\uc744 \ub2e4\uc2dc \uc124\uce58\ud558\uac70\ub098 \ub2e4\ub978 \uae30\uae30\uc5d0\uc11c \uc4f8 \ub54c\ub294 \uac19\uc740 \uc2a4\ud1a0\uc5b4 \uacc4\uc815\uc73c\ub85c \uad6c\ub9e4 \ubcf5\uc6d0\uc744 \ud558\uba74 \ub3fc\uc694.","\uc774\uc6a9\uad8c\uc740 \uc0b0 \uc2a4\ud1a0\uc5b4 \uacc4\uc815\uc5d0\uc11c\ub9cc \uc4f8 \uc218 \uc788\uc5b4\uc694. \ub2e4\ub978 \uc2a4\ud1a0\uc5b4 \uacc4\uc815\uc774\ub098 \uc6f9\uc73c\ub85c\ub294 \uc62e\uaca8\uc9c0\uc9c0 \uc54a\uc544\uc694.","\uc6f9\uc5d0\uc11c\ub294 \uc774\uc6a9\uad8c\uc744 \ud314\uc9c0 \uc54a\uc544\uc694."],t.s)
B.aHX=new A.ey("\uc81c7\uc870 (\uc774\uc6a9\uad8c \uad6c\ub9e4)",B.ax8)
B.arJ=s(["\uc774\uc6a9\uad8c\uc744 \uc0b0 \ub4a4 \uc774\uc6a9\uc744 \uc2dc\uc791\ud558\uc9c0 \uc54a\uc558\ub2e4\uba74, \uad6c\ub9e4 \ub0b4\uc6a9 \ud655\uc778(\uc2a4\ud1a0\uc5b4 \uc601\uc218\uc99d \ub4f1)\uc744 \ubc1b\uc740 \ub0a0\ubd80\ud130 7\uc77c \uc548\uc5d0 \uccad\uc57d\ucca0\ud68c\ub97c \ud560 \uc218 \uc788\uc5b4\uc694(\uc804\uc790\uc0c1\uac70\ub798\ubc95 \uc81c17\uc870 \uc81c1\ud56d).","\uc774\uc6a9\uc744 \uc2dc\uc791\ud55c \ub514\uc9c0\ud138 \ucf58\ud150\uce20\ub294 \uccad\uc57d\ucca0\ud68c\uac00 \uc81c\ud55c\ub3fc\uc694. \ud68c\uc0ac\ub294 \ubb34\ub8cc \uccb4\ud5d8\uc744 \uc81c\uacf5\ud558\uace0 \uad6c\ub9e4 \ud654\uba74\uc5d0 \uc774 \uc0ac\uc2e4\uc744 \uc54c\ub824, \ubc95\uc774 \uc815\ud55c \uc870\uce58\ub97c \ud588\uc5b4\uc694(\uc804\uc790\uc0c1\uac70\ub798\ubc95 \uc81c17\uc870 \uc81c2\ud56d \uc81c5\ud638, \uc81c6\ud56d, \uac19\uc740 \ubc95 \uc2dc\ud589\ub839 \uc81c21\uc870\uc7582).","\ub2e4\ub9cc \uc774\uc6a9\uad8c\uc758 \ub0b4\uc6a9\uc774 \ud45c\uc2dc\xb7\uad11\uace0\uc640 \ub2e4\ub974\uac70\ub098 \uacc4\uc57d\uacfc \ub2e4\ub974\uac8c \uc81c\uacf5\ub410\ub2e4\uba74, \uacf5\uae09\ubc1b\uc740 \ub0a0\ubd80\ud130 3\uac1c\uc6d4 \uc548\uc5d0, \uadf8 \uc0ac\uc2e4\uc744 \uc548 \ub0a0 \ub610\ub294 \uc54c \uc218 \uc788\uc5c8\ub358 \ub0a0\ubd80\ud130 30\uc77c \uc548\uc5d0 \uccad\uc57d\ucca0\ud68c\ub97c \ud560 \uc218 \uc788\uc5b4\uc694(\uc804\uc790\uc0c1\uac70\ub798\ubc95 \uc81c17\uc870 \uc81c3\ud56d).","\ud658\ubd88\uc740 \uc571\uc744 \uc0b0 \uc2a4\ud1a0\uc5b4\uc758 \ud658\ubd88 \uc808\ucc28\ub85c \uc2e0\uccad\ud558\uac70\ub098, support@sunworks.kr\ub85c \ubb38\uc758\ud574 \uc8fc\uc138\uc694. \ud68c\uc0ac\ub294 \uc2a4\ud1a0\uc5b4 \ud658\ubd88 \uc808\ucc28\ub97c \uc548\ub0b4\ud558\uace0 \ud544\uc694\ud55c \uc870\uce58\ub97c \ub3c4\uc640\uc694."],t.s)
B.aHO=new A.ey("\uc81c8\uc870 (\uccad\uc57d\ucca0\ud68c)",B.arJ)
B.aiR=s(["\ub9cc 19\uc138 \ubbf8\ub9cc \ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778(\ubcf4\ud638\uc790) \ub3d9\uc758 \uc5c6\uc774 \uc774\uc6a9\uad8c\uc744 \uc0c0\ub2e4\uba74, \ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc774\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uad6c\ub9e4\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\uc5b4\uc694(\ubbfc\ubc95 \uc81c5\uc870).","\ub2e4\ub9cc \ubbf8\uc131\ub144\uc790\uac00 \uc18d\uc784\uc218\ub85c \uc790\uc2e0\uc744 \uc131\ub144\uc790\ub85c \ubbff\uac8c \ud558\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\ub294 \uac83\ucc98\ub7fc \ubbff\uac8c \ud55c \uacbd\uc6b0(\ubbfc\ubc95 \uc81c17\uc870), \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc758 \ubc94\uc704 \uc548\uc5d0\uc11c \uc0b0 \uacbd\uc6b0(\ubbfc\ubc95 \uc81c6\uc870)\uc5d0\ub294 \ucde8\uc18c\uac00 \uc81c\ud55c\ub420 \uc218 \uc788\uc5b4\uc694.","\ucde8\uc18c\ub294 \uc81c8\uc870\uc640 \uac19\uc740 \ubc29\ubc95(\uc2a4\ud1a0\uc5b4 \ud658\ubd88 \uc694\uccad \ub610\ub294 \ubb38\uc758)\uc73c\ub85c \uc694\uccad\ud560 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aI4=new A.ey("\uc81c9\uc870 (\ubbf8\uc131\ub144\uc790\uc758 \uad6c\ub9e4)",B.aiR)
B.aib=s(["\uc798\ubabb \uacb0\uc81c\ub418\uac70\ub098 \ub354 \uacb0\uc81c\ub41c \uae08\uc561(\uacfc\uc624\uae08)\uc774 \uc788\uc73c\uba74 \ud68c\uc0ac\ub294 \uc774\ub97c \ub3cc\ub824\uc918\uc694(\ucf58\ud150\uce20\uc0b0\uc5c5 \uc9c4\ud765\ubc95 \uc81c28\uc870).","\uc2a4\ud1a0\uc5b4\uc5d0\uc11c \uacb0\uc81c\ud55c \uae08\uc561\uc740 \uc2a4\ud1a0\uc5b4 \ud658\ubd88 \uc808\ucc28\ub85c \ub3cc\ub824\ubc1b\uc744 \uc218 \uc788\uace0, \ubb38\uc758\ud558\uba74 \ud68c\uc0ac\uac00 \ud544\uc694\ud55c \uc870\uce58\ub97c \ub3c4\uc640\uc694."],t.s)
B.aHY=new A.ey("\uc81c10\uc870 (\uacfc\uc624\uae08\uc758 \ud658\ubd88)",B.aib)
B.ash=s(['\ucf58\ud150\uce20\uc5d0 \uc624\ub958\ub098 \uacb0\ud568\uc774 \uc788\uc73c\uba74 \ud68c\uc0ac\ub294 \uace0\uce58\uace0, \uace0\uce60 \uc218 \uc5c6\uc73c\uba74 \ud658\ubd88\ud574\uc694. \uc624\ub958\ub294 \ud559\uc2b5 \ud654\uba74\uc758 "\uc774\uc0c1\ud574\uc694" \ubc84\ud2bc\uc774\ub098 \ubb38\uc758\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.',"\ud68c\uc0ac\uac00 \uc11c\ube44\uc2a4\ub97c \uc911\ub2e8\ud558\ub824\uba74 \uc911\ub2e8 30\uc77c \uc804\ubd80\ud130 \uc571\uacfc \uc6f9 \ud398\uc774\uc9c0\uc5d0 \uc54c\ub824\uc694.","\uc11c\ube44\uc2a4\ub97c \uc911\ub2e8\ud574\ub3c4, \uc774\ubbf8 \uae30\uae30\uc5d0 \uc124\uce58\ub41c \uc571\uc758 \ud559\uc2b5\uc740 \uac00\ub2a5\ud55c \ubc94\uc704\uc5d0\uc11c \uacc4\uc18d \uc4f8 \uc218 \uc788\uac8c \ud574\uc694."],t.s)
B.aHP=new A.ey("\uc81c11\uc870 (\ucf58\ud150\uce20 \uacb0\ud568\uacfc \uc11c\ube44\uc2a4 \ubcc0\uacbd\xb7\uc911\ub2e8)",B.ash)
